// 1. EXTRACT LOGO IMAGE BINARY (Modern n8n Filesystem Fix)
const binaryData = $input.first().binary?.logo_file;

if (!binaryData) {
  throw new Error("Strict Mode Error: Could not find a binary file named 'logo_file'.");
}

// CRITICAL FIX: Extract the actual underlying file contents from the n8n disk storage
const binaryBuffer = await this.helpers.getBinaryDataBuffer(0, 'logo_file');
const base64String = binaryBuffer.toString('base64');

const logoDataUri = `data:${binaryData.mimeType};base64,${base64String}`;

// 2. FETCH GOOGLE SHEETS DATA
const inputData = $('Google Sheets Trigger').item.json;

const invoiceNo = inputData["Invoice #"];
const vendor = inputData["Vendor"] || "URAI Solution";
const description = inputData["Description"];
const subtotal = inputData["Subtotal"];
const tax = inputData["Tax(25%)"];
const total = inputData["Total"];
const status = (inputData["Status"] || "unpaid").toLowerCase();

// Helper function to convert Google Sheets serial days to YYYY-MM-DD
function convertSerialToDate(serial) {
  if (!serial || isNaN(serial)) return serial;
  const epoch = new Date(1899, 11, 30);
  const targetDate = new Date(epoch.getTime() + serial * 24 * 60 * 60 * 1000);
  const yyyy = targetDate.getFullYear();
  const mm = String(targetDate.getMonth() + 1).padStart(2, '0');
  const dd = String(targetDate.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

const issueDate = convertSerialToDate(inputData["Date"]);
const dueDate = convertSerialToDate(inputData["Due"]);

let badgeBg, badgeStroke, badgeText;
if (status === "paid") {
  badgeBg = "#e6f4ea"; badgeStroke = "#34a853"; badgeText = "#137333";
} else {
  badgeBg = "#fce8e6"; badgeStroke = "#ea4335"; badgeText = "#c5221f";
}

// 3. GENERATE DYNAMIC INVOICE SVG
const dynamicSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 1000" width="800" height="1000" style="background-color: #ffffff;">
   <style>
     .title { font-family: 'Helvetica Neue', Arial, sans-serif; font-size: 32px; font-weight: bold; fill: #1e293b; }
     .label { font-family: Arial, sans-serif; font-size: 12px; font-weight: bold; fill: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px; }
     .value { font-family: Arial, sans-serif; font-size: 14px; fill: #1e293b; font-weight: 500; }
     .th { font-family: Arial, sans-serif; font-size: 13px; font-weight: bold; fill: #475569; }
     .td { font-family: Arial, sans-serif; font-size: 14px; fill: #334155; }
     .total-label { font-family: Arial, sans-serif; font-size: 14px; font-weight: bold; fill: #475569; }
     .total-value { font-family: Arial, sans-serif; font-size: 16px; font-weight: bold; fill: #0f172a; }
     .footer { font-family: Arial, sans-serif; font-size: 12px; fill: #94a3b8; text-anchor: middle; }
     .divider { stroke: #e2e8f0; stroke-width: 1; }
     .table-header-bg { fill: #f8fafc; }
     .badge-bg { fill: ${badgeBg}; stroke: ${badgeStroke}; stroke-width: 1; }
     .badge-text { font-family: Arial, sans-serif; font-size: 11px; font-weight: bold; fill: ${badgeText}; text-transform: uppercase; letter-spacing: 1px; }
   </style>

   <g id="company-brand" transform="translate(50, 45)">
     <text x="65" y="34" font-family="'Helvetica Neue', Arial, sans-serif" font-size="24" font-weight="bold" fill="#0f172a">${vendor}</text>
   </g>

   <g transform="translate(650, 45)">
     <rect width="100" height="28" rx="6" class="badge-bg"/>
     <text x="50" y="18" class="badge-text" text-anchor="middle">${status}</text>
   </g>

   <text x="750" y="120" class="title" text-anchor="end">INVOICE</text>

   <text x="560" y="155" class="label" text-anchor="start">Invoice No:</text>
   <text x="750" y="155" class="value" text-anchor="end">${invoiceNo}</text>

   <text x="560" y="175" class="label" text-anchor="start">Issue Date:</text>
   <text x="750" y="175" class="value" text-anchor="end">${issueDate}</text>

   <text x="560" y="195" class="label" text-anchor="start">Due Date:</text>
   <text x="750" y="195" class="value" text-anchor="end">${dueDate}</text>

   <line x1="50" y1="220" x2="750" y2="220" class="divider" />

   <rect x="50" y="260" width="700" height="35" class="table-header-bg" rx="4"/>
   <text x="70" y="282" class="th" text-anchor="start">Line Item Description</text>
   <text x="730" y="282" class="th" text-anchor="end">Amount</text>
   <line x1="50" y1="295" x2="750" y2="295" class="divider" />

   <g id="item-row-1" transform="translate(0, 325)">
     <text x="70" y="0" class="td" text-anchor="start" font-weight="bold">${description}</text>
     <text x="730" y="0" class="td" text-anchor="end" font-weight="bold">$${subtotal}</text>
     <line x1="50" y1="20" x2="750" y2="20" class="divider" stroke-dasharray="4"/>
   </g>

   <g transform="translate(0, 400)">
     <text x="600" y="0" class="total-label" text-anchor="end">Subtotal:</text>
     <text x="730" y="0" class="value" text-anchor="end">$${subtotal}</text>

     <text x="600" y="25" class="total-label" text-anchor="end">Tax:</text>
     <text x="730" y="25" class="value" text-anchor="end">$${tax}</text>

     <line x1="530" y1="40" x2="750" y2="40" class="divider" />

     <text x="600" y="65" class="total-label" text-anchor="end" font-size="14" fill="#0f172a">Total Balance:</text>
     <text x="730" y="65" class="total-value" text-anchor="end" font-size="20" fill="#4f46e5">$${total}</text>
   </g>

   <line x1="50" y1="920" x2="750" y2="920" class="divider" />
   <text x="400" y="950" class="footer">Thank you for your business!</text>
   <text x="400" y="970" class="footer" font-size="10">This document was automatically generated via secure financial workflows.</text>
</svg>`;

return {
  raw_svg: dynamicSvg,
  logo_data_uri: logoDataUri
};

